import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Lesson 12: Writing Better Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-4/lesson-12.md","filePath":"en/modules/module-4/lesson-12.md"}'),s={name:"en/modules/module-4/lesson-12.md"};function n(l,e,r,p,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="lesson-12-writing-better-prompts" tabindex="-1">Lesson 12: Writing Better Prompts <a class="header-anchor" href="#lesson-12-writing-better-prompts" aria-label="Permalink to &quot;Lesson 12: Writing Better Prompts&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Master the techniques for writing effective prompts, so Codex can more accurately understand your needs ⏱️ <strong>Estimated Time</strong>: 20 minutes 🎯 <strong>Teaching Rhythm</strong>: Explanation + contrast examples</p></blockquote><hr><h2 id="i-prompt-quality-determines-result-quality" tabindex="-1">I. Prompt Quality Determines Result Quality <a class="header-anchor" href="#i-prompt-quality-determines-result-quality" aria-label="Permalink to &quot;I. Prompt Quality Determines Result Quality&quot;">​</a></h2><p>Codex is very capable, but its performance largely depends on the prompts you give it.</p><p><strong>A good prompt = Clear goal + Specific requirements + Explicit acceptance criteria</strong></p><hr><h2 id="ii-break-big-tasks-into-small-steps" tabindex="-1">II. Break Big Tasks Into Small Steps <a class="header-anchor" href="#ii-break-big-tasks-into-small-steps" aria-label="Permalink to &quot;II. Break Big Tasks Into Small Steps&quot;">​</a></h2><h3 id="❌-bad-prompt-help-me-build-a-website" tabindex="-1">❌ Bad prompt: &quot;Help me build a website&quot; <a class="header-anchor" href="#❌-bad-prompt-help-me-build-a-website" aria-label="Permalink to &quot;❌ Bad prompt: &quot;Help me build a website&quot;&quot;">​</a></h3><p>This prompt is too vague. Codex doesn&#39;t know what kind of website you want, what style, or what content to include.</p><h3 id="✅-better-prompt-help-me-build-a-personal-profile-webpage" tabindex="-1">✅ Better prompt: &quot;Help me build a personal profile webpage&quot; <a class="header-anchor" href="#✅-better-prompt-help-me-build-a-personal-profile-webpage" aria-label="Permalink to &quot;✅ Better prompt: &quot;Help me build a personal profile webpage&quot;&quot;">​</a></h3><p>Better, but still not specific enough.</p><h3 id="✅✅-even-better-prompt" tabindex="-1">✅✅ Even better prompt: <a class="header-anchor" href="#✅✅-even-better-prompt" aria-label="Permalink to &quot;✅✅ Even better prompt:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me build a personal profile webpage with the following requirements:</span></span>
<span class="line"><span>1. Include these sections: avatar, name, one-sentence bio, skills list, and contact info</span></span>
<span class="line"><span>2. Use a clean, modern design style</span></span>
<span class="line"><span>3. Primary color should be blue</span></span>
<span class="line"><span>4. Save the code as index.html</span></span></code></pre></div><p><strong>Key technique</strong>: Break a big task into several small steps and do them one at a time.</p><hr><h2 id="iii-tell-codex-to-plan-first-then-execute" tabindex="-1">III. Tell Codex to &quot;Plan First, Then Execute&quot; <a class="header-anchor" href="#iii-tell-codex-to-plan-first-then-execute" aria-label="Permalink to &quot;III. Tell Codex to &quot;Plan First, Then Execute&quot;&quot;">​</a></h2><p>Sometimes, directly asking Codex to execute may cause details to be missed. A better approach is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before you start, tell me your execution plan first. Wait for my confirmation before you begin.</span></span></code></pre></div><p>This way you can:</p><ul><li>Confirm that Codex understood your requirements</li><li>Adjust any deviations in the plan</li><li>Avoid Codex doing a lot of useless work</li></ul><hr><h2 id="iv-provide-background-information" tabindex="-1">IV. Provide Background Information <a class="header-anchor" href="#iv-provide-background-information" aria-label="Permalink to &quot;IV. Provide Background Information&quot;">​</a></h2><p>Codex doesn&#39;t know about your life and work context. You need to proactively provide it.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Background to Provide</th></tr></thead><tbody><tr><td>Organizing photos</td><td>&quot;These are photos from my trip to Japan last year. Organize them by city.&quot;</td></tr><tr><td>Writing an email</td><td>&quot;This is an email to a client. The tone should be formal. The topic is about a project delay.&quot;</td></tr><tr><td>Data analysis</td><td>&quot;This is our sales data, containing four columns: date, product, quantity, and amount.&quot;</td></tr></tbody></table><blockquote><p>💡 <strong>Tip</strong>: More background info is not always better. Relevance is what matters.</p></blockquote><hr><h2 id="v-use-acceptance-criteria-to-tell-codex-what-done-looks-like" tabindex="-1">V. Use &quot;Acceptance Criteria&quot; to Tell Codex What &quot;Done&quot; Looks Like <a class="header-anchor" href="#v-use-acceptance-criteria-to-tell-codex-what-done-looks-like" aria-label="Permalink to &quot;V. Use &quot;Acceptance Criteria&quot; to Tell Codex What &quot;Done&quot; Looks Like&quot;">​</a></h2><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me clean up this document. Requirements:</span></span>
<span class="line"><span>1. Remove all empty lines</span></span>
<span class="line"><span>2. Unify heading format (level 1 headings use #, level 2 headings use ##)</span></span>
<span class="line"><span>3. Check and fix typos</span></span>
<span class="line"><span>4. Finally, tell me what changes you made</span></span></code></pre></div><p>Notice the last item — <strong>asking Codex to tell you what it did</strong>. This way you can quickly verify whether the result meets your expectations.</p><hr><h2 id="vi-prompt-templates" tabindex="-1">VI. Prompt Templates <a class="header-anchor" href="#vi-prompt-templates" aria-label="Permalink to &quot;VI. Prompt Templates&quot;">​</a></h2><h3 id="file-operations" tabindex="-1">File Operations <a class="header-anchor" href="#file-operations" aria-label="Permalink to &quot;File Operations&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please help me [action] [object], [specific requirements], [acceptance criteria]</span></span></code></pre></div><h3 id="content-generation" tabindex="-1">Content Generation <a class="header-anchor" href="#content-generation" aria-label="Permalink to &quot;Content Generation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please help me [action] a [type] about [topic], with [format/style], [acceptance criteria]</span></span></code></pre></div><h3 id="data-analysis" tabindex="-1">Data Analysis <a class="header-anchor" href="#data-analysis" aria-label="Permalink to &quot;Data Analysis&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please help me analyze [data source], find [focus point], output as [format], [acceptance criteria]</span></span></code></pre></div><hr><h2 id="vii-in-lesson-practice" tabindex="-1">VII. In-Lesson Practice <a class="header-anchor" href="#vii-in-lesson-practice" aria-label="Permalink to &quot;VII. In-Lesson Practice&quot;">​</a></h2><ol><li>Choose a task you want Codex to complete.</li><li>Try it once with a vague prompt.</li><li>Try it again with a clear prompt (following the templates above).</li><li>Compare the difference between the two results.</li></ol><hr><h2 id="viii-summary" tabindex="-1">VIII. Summary <a class="header-anchor" href="#viii-summary" aria-label="Permalink to &quot;VIII. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Technique</th><th>Description</th></tr></thead><tbody><tr><td>Break down tasks</td><td>Break big tasks into small steps, complete them gradually</td></tr><tr><td>Plan before executing</td><td>Ask Codex to give a plan first, confirm before executing</td></tr><tr><td>Provide background</td><td>Proactively tell Codex relevant context</td></tr><tr><td>Acceptance criteria</td><td>Clearly tell Codex what &quot;done&quot; looks like</td></tr></tbody></table><hr><h2 id="ix-next-step" tabindex="-1">IX. Next Step <a class="header-anchor" href="#ix-next-step" aria-label="Permalink to &quot;IX. Next Step&quot;">​</a></h2><p><a href="./lesson-13.html">→ Lesson 13: Security &amp; Permissions</a></p>`,49)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
